230→        let msg = bar.message();
231→        assert!(msg.contains("line 1"));
232→        assert!(msg.contains("line 2"));
233→
234→        // Ring buffer evicts oldest line
235→        callback(OutputLine::Stdout("line 3".to_string()));
236→        let msg = bar.message();
237→        assert!(!msg.contains("line 1"));
238→        assert!(msg.contains("line 2"));
239→        assert!(msg.contains("line 3"));
240→
241→        bar.finish();
242→    }
243→
244→    #[test]
245→    fn live_output_callback_skips_empty_lines() {
246→        let bar = ProgressBar::hidden();
247→        let callback = live_output_callback(bar.clone(), "Running...".to_string(), 4, 2);
248→
249→        // Send an empty line — should not cause a newline in the message
250→        callback(OutputLine::Stdout("".to_string()));
251→
252→        // Now send a real line — the message should have exactly one output line
253→        callback(OutputLine::Stdout("real output".to_string()));
254→        let msg = bar.message();
255→        assert!(msg.contains("real output"));
256→        // Only one newline (base message + one output line)
257→        assert_eq!(msg.matches('\n').count(), 1);
258→
259→        bar.finish();
260→    }
261→
262→    #[test]
263→    fn live_output_callback_truncates_long_lines() {
264→        let bar = ProgressBar::hidden();
265→        let callback = live_output_callback(bar.clone(), "Running...".to_string(), 4, 2);
266→
267→        let long_line = "x".repeat(100);
268→        callback(OutputLine::Stdout(long_line));
269→        let msg = bar.message();
270→        assert!(msg.contains("..."));
271→        // Should not contain the full 100-char line
272→        assert!(!msg.contains(&"x".repeat(100)));
273→
274→        bar.finish();
275→    }
276→}
