817→                }
818→            }
819→
820→            // Abort: stop processing further steps
821→            if workflow_aborted {
822→                all_success = false;
823→                break;
824→            }
825→        }
826→
827→        // Finish progress bar
828→        ui.finish_workflow_progress();
829→
830→        let mut all_skipped: Vec<String> = skipped.into_iter().collect();
831→        all_skipped.extend(env_skipped);
832→
833→        Ok(WorkflowResult {
834→            workflow: workflow_name.to_string(),
835→            steps: results,
836→            skipped: all_skipped,
837→            duration: start.elapsed(),
838→            success: all_success,
839→            aborted: workflow_aborted,
840→        })
841→    }
842→
843→    /// Build the dependency graph for the given workflow.
844→    pub fn build_graph(&self, workflow: &str) -> Result<DependencyGraph> {
845→        let workflow_config = self.config.workflows.get(workflow).ok_or_else(|| {
846→            BivvyError::ConfigValidationError {
847→                message: format!("Unknown workflow: {}", workflow),
848→            }
849→        })?;
850→
851→        let mut builder = DependencyGraph::builder();
852→
853→        for step_name in &workflow_config.steps {
854→            let step =
855→                self.steps
856→                    .get(step_name)
857→                    .ok_or_else(|| BivvyError::ConfigValidationError {
858→                        message: format!(
859→                            "Workflow '{}' references unknown step '{}'",
860→                            workflow, step_name
861→                        ),
862→                    })?;
863→
864→            builder = builder.add_step(step_name.clone(), step.depends_on.clone());
865→        }
866→
867→        builder.build()
868→    }
869→}

  1→//! Output mode and writer.
  2→
  3→use std::io::Write;
  4→use std::str::FromStr;
  5→
  6→/// Output verbosity mode.
  7→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  8→pub enum OutputMode {
  9→    /// Show all output including command output.
 10→    Verbose,
 11→    /// Show progress and status only.
 12→    #[default]
 13→    Normal,
 14→    /// Show minimal output (spinners + final status).
 15→    Quiet,
 16→    /// Show nothing except errors.
 17→    Silent,
 18→}
 19→
 20→impl FromStr for OutputMode {
 21→    type Err = String;
 22→
 23→    fn from_str(s: &str) -> Result<Self, Self::Err> {
 24→        match s.to_lowercase().as_str() {
 25→            "verbose" => Ok(Self::Verbose),
 26→            "normal" => Ok(Self::Normal),
 27→            "quiet" => Ok(Self::Quiet),
 28→            "silent" => Ok(Self::Silent),
 29→            _ => Err(format!("unknown output mode: {}", s)),
 30→        }
 31→    }
 32→}
 33→
 34→impl From<crate::config::schema::OutputMode> for OutputMode {
 35→    fn from(config_mode: crate::config::schema::OutputMode) -> Self {
 36→        match config_mode {
 37→            crate::config::schema::OutputMode::Verbose => Self::Verbose,
 38→            crate::config::schema::OutputMode::Quiet => Self::Quiet,
 39→            crate::config::schema::OutputMode::Silent => Self::Silent,
 40→        }
 41→    }
 42→}
 43→
 44→impl OutputMode {
 45→    /// Check if this mode shows command output.
 46→    pub fn shows_command_output(&self) -> bool {
 47→        matches!(self, Self::Verbose)
 48→    }
 49→
 50→    /// Check if this mode shows progress spinners.
 51→    pub fn shows_spinners(&self) -> bool {
 52→        matches!(self, Self::Verbose | Self::Normal | Self::Quiet)
 53→    }
 54→
 55→    /// Check if this mode shows status messages.
 56→    pub fn shows_status(&self) -> bool {
 57→        !matches!(self, Self::Silent)
 58→    }
 59→}
 60→
 61→/// Output writer that respects output mode.
 62→#[derive(Debug)]
 63→pub struct Output {
 64→    mode: OutputMode,
 65→}
 66→
 67→impl Output {
 68→    /// Create a new output writer.
 69→    pub fn new(mode: OutputMode) -> Self {
 70→        Self { mode }
 71→    }
 72→
 73→    /// Get the output mode.
 74→    pub fn mode(&self) -> OutputMode {
 75→        self.mode
 76→    }
 77→
 78→    /// Write a line if the mode allows status messages.
 79→    pub fn println(&self, msg: &str) {
 80→        if self.mode.shows_status() {
 81→            println!("{}", msg);
 82→        }
 83→    }
 84→
 85→    /// Write command output if verbose mode.
 86→    pub fn command_output(&self, output: &str) {
 87→        if self.mode.shows_command_output() {
 88→            print!("{}", output);
 89→            let _ = std::io::stdout().flush();
 90→        }
 91→    }
 92→}
 93→
 94→#[cfg(test)]
 95→mod tests {
 96→    use super::*;
 97→
 98→    #[test]
 99→    fn output_mode_from_str() {
100→        assert_eq!("verbose".parse::<OutputMode>(), Ok(OutputMode::Verbose));
101→        assert_eq!("QUIET".parse::<OutputMode>(), Ok(OutputMode::Quiet));
102→        assert!("invalid".parse::<OutputMode>().is_err());
103→    }
104→
105→    #[test]
106→    fn output_mode_shows_command_output() {
107→        assert!(OutputMode::Verbose.shows_command_output());
108→        assert!(!OutputMode::Normal.shows_command_output());
109→        assert!(!OutputMode::Quiet.shows_command_output());
110→        assert!(!OutputMode::Silent.shows_command_output());
111→    }
112→
113→    #[test]
114→    fn output_mode_shows_spinners() {
115→        assert!(OutputMode::Verbose.shows_spinners());
116→        assert!(OutputMode::Normal.shows_spinners());
117→        assert!(OutputMode::Quiet.shows_spinners());
118→        assert!(!OutputMode::Silent.shows_spinners());
119→    }
120→
121→    #[test]
122→    fn output_mode_shows_status() {
123→        assert!(OutputMode::Verbose.shows_status());
124→        assert!(OutputMode::Normal.shows_status());
125→        assert!(OutputMode::Quiet.shows_status());
126→        assert!(!OutputMode::Silent.shows_status());
127→    }
128→
129→    #[test]
130→    fn output_mode_default() {
131→        assert_eq!(OutputMode::default(), OutputMode::Normal);
132→    }
133→
134→    #[test]
135→    fn output_new_and_mode() {
136→        let output = Output::new(OutputMode::Quiet);
137→        assert_eq!(output.mode(), OutputMode::Quiet);
138→    }
139→
140→    #[test]
141→    fn from_config_verbose() {
142→        let config_mode = crate::config::schema::OutputMode::Verbose;
143→        let ui_mode: OutputMode = config_mode.into();
144→        assert_eq!(ui_mode, OutputMode::Verbose);
145→    }
146→
147→    #[test]
148→    fn from_config_quiet() {
149→        let config_mode = crate::config::schema::OutputMode::Quiet;
150→        let ui_mode: OutputMode = config_mode.into();
151→        assert_eq!(ui_mode, OutputMode::Quiet);
152→    }
153→
154→    #[test]
155→    fn from_config_silent() {
156→        let config_mode = crate::config::schema::OutputMode::Silent;
157→        let ui_mode: OutputMode = config_mode.into();
158→        assert_eq!(ui_mode, OutputMode::Silent);
159→    }
160→}
